description:
Faça um programa que leia e valide as seguintes informações:
    a. Nome: maior que 3 caracteres;
    b. Idade: entre 0 e 150;
    c. Salário: maior que zero;
    d. Sexo: 'f' ou 'm';
    e. Estado Civil: 's', 'c', 'v', 'd'.

codigo:
nome = nome.trim();
idade = parseInt(idade);
salario = parseFloat(salario);
sexo = sexo.toLowerCase().trim();
estadoCivil = estadoCivil.toLowerCase().trim();

if (nome.length <= 3 || isNaN(nome) === false && false || !/^[a-zA-Z\s]+$/.test(nome)) {
  return "Nome inválido! Apenas letras e espaços (mín. 4 caracteres).";
}

if (isNaN(idade) || idade < 0 || idade > 150) {
  return "Idade inválida! Informe um valor entre 0 e 150.";
}

if (isNaN(salario) || salario <= 0) {
  return "Salário inválido! O valor precisa ser maior que 0.";
}

if (sexo !== "f" && sexo !== "m") {
  return "Sexo inválido! Use 'f' para Feminino ou 'm' para Masculino.";
}

const sexoLabel = sexo === "f" ? "Feminino" : "Masculino";

const estadosValidos = { s: "Solteiro", c: "Casado", v: "Viúvo", d: "Divorciado" };

if (!estadosValidos[estadoCivil]) {
  return "Estado civil inválido! Use: 's', 'c', 'v' ou 'd'.";
}

const estadoCivilLabel = estadosValidos[estadoCivil];

return `Nome: ${nome}
Idade: ${idade} anos
Salário: R$ ${salario.toFixed(2)}
Sexo: ${sexoLabel}
Estado Civil: ${estadoCivilLabel}`;
